H_memory_limit.command:
docker run --name phase7a-mem-00148769 --network none --memory 100m --memory-swap 100m python:3.12-slim python3 -c import time
chunks = []
try:
    for i in range(1, 40):
        b = bytearray(20 * 1024 * 1024)
        for j in range(0, len(b), 4096):
            b[j] = 1
        chunks.append(b)
        print('allocated_mb=' + str(i * 20), flush=True)
        time.sleep(0.05)
    print('COMPLETED_WITHOUT_OOM')
except MemoryError:
    print('PYTHON_MEMORY_ERROR')
